IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = 'MyDatabase')\nBEGIN\n    CREATE DATABASE MyDatabase;\nEND\nGO\n\nUSE MyDatabase;\nGO\n\nIF OBJECT_ID('dbo.GameResult', 'U') IS NULL\nBEGIN\n    CREATE TABLE dbo.GameResult (\n        GameHash NVARCHAR(100) NOT NULL,\n        CredentialHash CHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,\n        Score INT NOT NULL,\n        Username NVARCHAR(255) NULL,\n        CreatedAtUtc DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),\n        CONSTRAINT PK_GameResult PRIMARY KEY (GameHash, CredentialHash)\n    );\nEND;\n\nIF COL_LENGTH('dbo.GameResult', 'Username') IS NULL\nBEGIN\n    ALTER TABLE dbo.GameResult ADD Username NVARCHAR(255) NULL;\nEND;\n\nIF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Prompt')\nBEGIN\n    CREATE TABLE Prompt (\n        Text NVARCHAR(120) NOT NULL,\n        Language NVARCHAR(5) NOT NULL,\n        Category NVARCHAR(64) NOT NULL CONSTRAINT DF_Prompt_Category DEFAULT N'general',\n        Kind VARCHAR(16) NOT NULL CONSTRAINT DF_Prompt_Kind DEFAULT 'word',\n        CONSTRAINT PK_Prompt PRIMARY KEY (Text, Language),\n        CONSTRAINT CK_Prompt_Kind CHECK (Kind IN ('word', 'phrase', 'saying')),\n        CONSTRAINT CK_Prompt_Category CHECK (LEN(LTRIM(RTRIM(Category))) BETWEEN 1 AND 64)\n    );\nEND\nGO\n\nIF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Account')\nBEGIN\n    CREATE TABLE Account (\n        Id NVARCHAR(100) PRIMARY KEY,\n        Email NVARCHAR(255),\n        Name NVARCHAR(255),\n        Score INT NOT NULL CONSTRAINT DF_Account_Score DEFAULT 0\n    );\nEND\nGO\n\nIF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'AccountScoreAward')\nBEGIN\n    CREATE TABLE AccountScoreAward (\n        GameHash NVARCHAR(100) NOT NULL,\n        CredentialHash CHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,\n        AccountId NVARCHAR(100) NOT NULL,\n        Score INT NOT NULL,\n        CreatedAtUtc DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),\n        CONSTRAINT PK_AccountScoreAward PRIMARY KEY (GameHash, CredentialHash)\n    );\nEND\nGO\n\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.AccountScoreAward') AND name = 'UX_AccountScoreAward_Game_Account')\nBEGIN\n    CREATE UNIQUE INDEX UX_AccountScoreAward_Game_Account ON dbo.AccountScoreAward (GameHash, AccountId);\nEND\nGO\n\nIF NOT EXISTS (SELECT TOP 1 1 FROM Prompt)\nBEGIN\n    INSERT INTO Prompt (Text, Language) VALUES\n    ('apple', 'en'), (N'jabłko', 'pl'),\n    ('ball', 'en'), (N'piłka', 'pl'),\n    ('book', 'en'), (N'książka', 'pl'),\n    ('chair', 'en'), (N'krzesło', 'pl'),\n    ('lamp', 'en'), (N'lampa', 'pl'),\n    ('fan', 'en'), (N'wentylator', 'pl'),\n    ('shirt', 'en'), (N'koszula', 'pl'),\n    ('pants', 'en'), (N'spodnie', 'pl'),\n    ('glasses', 'en'), (N'okulary', 'pl'),\n    ('wallet', 'en'), (N'portfel', 'pl'),\n    ('blanket', 'en'), (N'koc', 'pl'),\n    ('shovel', 'en'), (N'łopata', 'pl'),\n    ('ladder', 'en'), (N'drabina', 'pl'),\n    ('hammer', 'en'), (N'młotek', 'pl'),\n    ('key', 'en'), (N'klucz', 'pl'),\n    ('rope', 'en'), (N'lina', 'pl'),\n    ('watch', 'en'), (N'zegarek', 'pl'),\n    ('telescope', 'en'), (N'teleskop', 'pl'),\n    ('umbrella', 'en'), (N'parasol', 'pl'),\n    ('pencil', 'en'), (N'ołówek', 'pl'),\n    ('pen', 'en'), (N'długopis', 'pl'),\n    ('scissors', 'en'), (N'nożyczki', 'pl'),\n    ('paper', 'en'), (N'papier', 'pl'),\n    ('bottle', 'en'), (N'butelka', 'pl'),\n    ('bucket', 'en'), (N'wiadro', 'pl'),\n    ('candle', 'en'), (N'świeca', 'pl'),\n    ('pillow', 'en'), (N'poduszka', 'pl'),\n    ('spoon', 'en'), (N'łyżka', 'pl'),\n    ('fork', 'en'), (N'widelec', 'pl'),\n    ('knife', 'en'), (N'nóż', 'pl'),\n    ('cup', 'en'), (N'kubek', 'pl'),\n    ('broom', 'en'), (N'miotła', 'pl'),\n    ('nail', 'en'), (N'gwóźdź', 'pl'),\n    ('window', 'en'), (N'okno', 'pl'),\n    ('door', 'en'), (N'drzwi', 'pl'),\n    ('television', 'en'), (N'telewizor', 'pl'),\n    ('camera', 'en'), (N'aparat', 'pl'),\n    ('computer', 'en'), (N'komputer', 'pl'),\n    ('remote', 'en'), (N'pilot', 'pl'),\n    ('couch', 'en'), (N'kanapa', 'pl'),\n    ('carpet', 'en'), (N'dywan', 'pl'),\n    ('shelf', 'en'), (N'półka', 'pl'),\n    ('mirror', 'en'), (N'lustro', 'pl'),\n    ('picture', 'en'), (N'obraz', 'pl'),\n    ('clock', 'en'), (N'zegar', 'pl'),\n    ('toothbrush', 'en'), (N'szczoteczka', 'pl'),\n    ('soap', 'en'), (N'mydło', 'pl'),\n    ('toothpaste', 'en'), (N'pasta', 'pl'),\n    ('shampoo', 'en'), (N'szampon', 'pl'),\n    ('towel', 'en'), (N'ręcznik', 'pl'),\n    ('bicycle', 'en'), (N'rower', 'pl'),\n    ('calculator', 'en'), (N'kalkulator', 'pl'),\n    ('mouse', 'en'), (N'mysz', 'pl'),\n    ('keyboard', 'en'), (N'klawiatura', 'pl'),\n    ('charger', 'en'), (N'ładowarka', 'pl'),\n    ('tablet', 'en'), (N'tablet', 'pl'),\n    ('notebook', 'en'), (N'zeszyt', 'pl'),\n    ('radio', 'en'), (N'radio', 'pl');\nEND\nGO\n\n\nIF NOT EXISTS (SELECT 1 FROM Prompt WHERE Kind IN ('phrase', 'saying'))\nBEGIN\n    INSERT INTO Prompt (Text, Language, Category, Kind) VALUES\n    ('break the ice', 'en', N'idioms', 'saying'),\n    ('piece of cake', 'en', N'idioms', 'saying'),\n    ('raining cats and dogs', 'en', N'idioms', 'saying'),\n    ('walking the dog', 'en', N'everyday activities', 'phrase'),\n    ('making breakfast', 'en', N'everyday activities', 'phrase'),\n    ('missing the bus', 'en', N'everyday situations', 'phrase'),\n    ('birthday party', 'en', N'events', 'phrase'),\n    ('treasure hunt', 'en', N'games', 'phrase'),\n    (N'bułka z masłem', 'pl', N'powiedzenia', 'saying'),\n    (N'robić z igły widły', 'pl', N'powiedzenia', 'saying'),\n    (N'leje jak z cebra', 'pl', N'powiedzenia', 'saying'),\n    (N'wyprowadzać psa', 'pl', N'codzienne czynności', 'phrase'),\n    (N'robić śniadanie', 'pl', N'codzienne czynności', 'phrase'),\n    (N'spóźnić się na autobus', 'pl', N'codzienne sytuacje', 'phrase'),\n    (N'przyjęcie urodzinowe', 'pl', N'wydarzenia', 'phrase'),\n    (N'poszukiwanie skarbu', 'pl', N'gry', 'phrase');\nEND\nGO\n
